/* Ligerim — painel multi-cooperativa leve, sem framework */
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const state={token:localStorage.getItem('lg_token')||'',user:null,page:'dashboard',selectedCoop:localStorage.getItem('lg_coop')||'',cache:{},online:false,watchId:null,map:null,markers:new Map(),timer:null};
const roles={platform_admin:'Administrador Master',cooperative_admin:'Administrador da cooperativa',dispatcher:'Atendente da Base',establishment:'Estabelecimento',driver:'Cooperado'};
const statusText={active:'Ativo',inactive:'Inativo',blocked:'Bloqueado',new:'Nova',offered:'Oferecida',assigned:'Atribuída',accepted:'Aceita',to_pickup:'Indo para coleta',at_pickup:'Na coleta',picked_up:'Coletada',in_route:'Em rota',delivered:'Entregue',cancelled:'Cancelada',problem:'Problema',scheduled:'Agendada',confirmed:'Confirmada',completed:'Concluída',absent:'Ausente',open:'Em aberto',paid:'Pago',revoked:'Revogada',paused:'Pausado'};
const pageMeta={dashboard:['Visão geral','▦'],cooperatives:['Cooperativas','◉'],users:['Usuários','♙'],establishments:['Estabelecimentos','▤'],drivers:['Cooperados','♟'],contracts:['Contratos','▥'],bases:['Bases','⌂'],services:['Serviços adicionais','＋'],shifts:['Horários fixos','◷'],schedules:['Escalas','▦'],deliveries:['Entregas','➜'],tracking:['Cooperados online','⌖'],team:['Equipe de hoje','♟'],routes:['Montar rota','↝'],prices:['Tabela por contrato','＄'],financial:['Ganhos e descontos','◌'],deductions:['Impostos e rateios','％'],closings:['Fechamento semanal','✓'],advances:['Adiantamentos','↗'],credits:['Créditos de clientes','◈'],integrations:['Integrações e API','⌘'],attendance:['Check-in e check-out','▣'],settings:['Configurações','⚙'],audit:['Auditoria','≡'],account:['Minha conta','●']};
const navByRole={
 platform_admin:[['Plataforma',['dashboard','cooperatives','audit']],['Conta',['account']]],
 cooperative_admin:[['Minha cooperativa',['dashboard','users','establishments','drivers','contracts','bases','services','shifts']],['Operação',['schedules','attendance','deliveries','team','tracking']],['Financeiro',['financial','deductions','closings','advances','credits']],['Integrações',['prices','integrations']],['Configuração',['settings','account']]],
 dispatcher:[['Operação',['dashboard','establishments','drivers','contracts','bases','services','shifts','schedules','attendance','deliveries','tracking']],['Consulta',['prices','account']]],
 establishment:[['Meu estabelecimento',['dashboard','deliveries','team','tracking','schedules','prices','integrations','account']]],
 driver:[['Meu aplicativo',['dashboard','attendance','deliveries','routes','schedules','financial','advances','account']]]
};
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function money(c){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(c||0)/100)}
function dateOnly(v){if(!v)return '—';const d=new Date(String(v).length===10?`${v}T12:00:00`:v);return Number.isNaN(d.getTime())?esc(v):d.toLocaleDateString('pt-BR')}
function dateTime(v){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?esc(v):d.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}
function timeOnly(v){return v?String(v).slice(11,16):'—'}
function isoDate(d=new Date()){const x=new Date(d.getTime()-d.getTimezoneOffset()*60000);return x.toISOString().slice(0,10)}
function addDays(date,n){const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+n);return isoDate(d)}
function mondayOf(date){const d=new Date(`${date}T12:00:00`);const day=d.getDay();d.setDate(d.getDate()-(day===0?6:day-1));return isoDate(d)}
function monthBounds(date){const d=new Date(`${date}T12:00:00`);return[isoDate(new Date(d.getFullYear(),d.getMonth(),1,12)),isoDate(new Date(d.getFullYear(),d.getMonth()+1,0,12))]}
function badge(v){return `<span class="badge ${esc(v)}">${esc(statusText[v]||v||'—')}</span>`}
function initials(n){return String(n||'LG').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function toast(msg,type='success'){const e=document.createElement('div');e.className=`toast ${type}`;e.textContent=msg;$('#toast-container').append(e);setTimeout(()=>e.remove(),4500)}
function loading(on){$('#loading').classList.toggle('hidden',!on)}
function query(obj={}){const p=new URLSearchParams();Object.entries(obj).forEach(([k,v])=>{if(v!==''&&v!==null&&v!==undefined)p.set(k,v)});return p.toString()?`?${p}`:''}
function scopeParams(extra={}){return {...extra,...(state.user?.role==='platform_admin'&&state.selectedCoop?{cooperative_id:state.selectedCoop}:{})}}
function scopeBody(body={}){if(state.user?.role==='platform_admin'&&state.selectedCoop)return {...body,cooperative_id:state.selectedCoop};if(state.user?.cooperative_id)return {...body,cooperative_id:state.user.cooperative_id};return body}
async function api(path,opt={}){const headers={'Content-Type':'application/json',...(opt.headers||{})};if(state.token)headers.Authorization=`Bearer ${state.token}`;let res;try{res=await fetch(path,{...opt,headers,body:opt.body&&typeof opt.body!=='string'?JSON.stringify(opt.body):opt.body})}catch{throw new Error('Servidor desconectado. Mantenha o PowerShell com npm run dev aberto.')}let data={};try{data=await res.json()}catch{}if(res.status===401&&state.token){logout(false);throw new Error('Sessão expirada. Entre novamente.')}if(!res.ok||data.ok===false){const e=new Error(data.error||`Erro ${res.status}`);e.data=data;e.status=res.status;throw e}return data}
function formObject(form){const o={};new FormData(form).forEach((v,k)=>{if(k.endsWith('[]')){const n=k.slice(0,-2);(o[n]??=[]).push(v)}else o[k]=v});$$('input[type=checkbox]:not([name$="[]"])',form).forEach(x=>o[x.name]=x.checked);return o}
function openModal(title,html){
 const modal=$('#modal'),body=$('#modal-body');
 $('#modal-title').textContent=title;body.innerHTML=html;modal.classList.remove('hidden');document.body.classList.add('modal-open');
 modal.scrollTop=0;modal.querySelector('.modal-card')?.scrollTo?.({top:0});
 $$('[data-close-modal]',modal).forEach(button=>button.onclick=event=>{event.preventDefault();event.stopPropagation();closeModal()});
 setTimeout(()=>body.querySelector('input:not([type=hidden]):not([disabled]),select:not([disabled]),textarea:not([disabled]),button')?.focus(),80)
}
function closeModal(){try{stopQrScanner()}catch{}const modal=$('#modal');if(!modal)return;modal.classList.add('hidden');const body=$('#modal-body');if(body)body.innerHTML='';document.body.classList.remove('modal-open')}
function field(label,name,value='',type='text',attrs=''){return `<label>${esc(label)}<input name="${esc(name)}" type="${esc(type)}" value="${esc(value??'')}" ${attrs}></label>`}
function textarea(label,name,value='',attrs=''){return `<label class="full">${esc(label)}<textarea name="${esc(name)}" ${attrs}>${esc(value??'')}</textarea></label>`}
function selectField(label,name,items=[],selected='',blank='Selecione',attrs=''){return `<label>${esc(label)}<select name="${esc(name)}" ${attrs}><option value="">${esc(blank)}</option>${items.map(x=>`<option value="${esc(x.id)}" ${String(x.id)===String(selected)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`}
function buttons(text='Salvar'){return `<div class="form-actions"><button type="button" class="btn" data-close-modal>Cancelar</button><button type="submit" class="btn primary">${esc(text)}</button></div>`}
function empty(title='Nenhum registro',text='Cadastre o primeiro item para começar.'){return `<div class="empty"><strong>${esc(title)}</strong>${esc(text)}</div>`}
function panel(title,body,tools=''){return `<section class="panel"><header class="panel-header"><h2>${esc(title)}</h2>${tools}</header>${body.startsWith('<div class="table-wrap"')||body.startsWith('<div class="empty"')?body:`<div class="panel-body">${body}</div>`}</section>`}
function table(cols,rows,actions){if(!rows?.length)return empty();return `<div class="table-wrap"><table class="data-table"><thead><tr>${cols.map(c=>`<th>${esc(c.label)}</th>`).join('')}${actions?'<th>Ações</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td class="${c.wrap?'wrap':''}">${c.render?c.render(r):esc(r[c.key]??'—')}</td>`).join('')}${actions?`<td><div class="actions">${actions(r)}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function cards(items){return `<div class="cards">${items.map(x=>`<div class="stat-card"><div class="icon">${x.icon||'•'}</div><strong>${x.value}</strong><small>${esc(x.label)}</small></div>`).join('')}</div>`}
function setPage(name){$('#page-title').textContent=pageMeta[name]?.[0]||name;$('#page-kicker').textContent=state.user?.cooperative_name||(state.user?.role==='platform_admin'?(state.selectedCoopName||'Todas as cooperativas'):'ChegaJá')}
function renderNav(){const groups=navByRole[state.user.role]||[];$('#sidebar-nav').innerHTML=groups.map(([g,pages])=>`<div class="nav-section">${esc(g)}</div>${pages.map(p=>`<button class="nav-item ${state.page===p?'active':''}" data-page="${p}"><span>${pageMeta[p]?.[1]||'•'}</span>${pageMeta[p]?.[0]||p}</button>`).join('')}`).join('');$$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page))}
function showAuth(view='login'){['login','forgot','reset'].forEach(x=>$(`#${x}-form`).classList.toggle('hidden',x!==view));$('#auth-screen').classList.remove('hidden');$('#app-shell').classList.add('hidden');$('#tracking-screen').classList.add('hidden');$('#customer-screen').classList.add('hidden')}
function showApp(){$('#auth-screen').classList.add('hidden');$('#tracking-screen').classList.add('hidden');$('#customer-screen').classList.add('hidden');$('#app-shell').classList.remove('hidden');const establishmentAccess=state.user.role==='establishment',footerName=establishmentAccess?(state.user.establishment_name||state.user.name):state.user.name,footerLogo=establishmentAccess?state.user.establishment_logo_url:null,avatar=$('#user-avatar');$('#user-name').textContent=footerName;$('#user-role').textContent=roles[state.user.role]||state.user.role;avatar.classList.remove('has-logo');avatar.replaceChildren();if(footerLogo){const image=document.createElement('img');image.src=footerLogo;image.alt=`Logo de ${footerName}`;image.onerror=()=>{avatar.classList.remove('has-logo');avatar.textContent=initials(footerName)};avatar.classList.add('has-logo');avatar.appendChild(image)}else avatar.textContent=initials(footerName);$('#tenant-name').textContent=state.user.cooperative_name||'Administração Master';$('#online-control').classList.toggle('hidden',state.user.role!=='driver');renderMasterFilter();renderNav();const defaultPage=state.user.role==='dispatcher'?'bases':'dashboard';navigate(location.hash.slice(1)||defaultPage,false)}
async function loadMe(){const d=await api('/api/auth/me');state.user=d.user;state.online=Boolean(d.user?.online);showApp();updateOnlineControl();if(state.online)startLocation()}
function logout(msg=true){localStorage.removeItem('lg_token');state.token='';state.user=null;stopLocation();if(msg)toast('Sessão encerrada.');showAuth('login')}
async function navigate(page,push=true){const allowed=(navByRole[state.user?.role]||[]).flatMap(x=>x[1]);if(!pageMeta[page]||!allowed.includes(page))page='dashboard';state.page=page;if(push)location.hash=page;renderNav();setPage(page);$('#sidebar').classList.remove('open');loading(true);try{await (pages[page]||pages.dashboard)()}catch(e){$('#page-content').innerHTML=empty('Não foi possível carregar',e.message);toast(e.message,'error')}finally{loading(false)}}
async function renderMasterFilter(){const sel=$('#master-coop-filter');if(state.user.role!=='platform_admin'){sel.classList.add('hidden');return}const d=await api('/api/app/platform/cooperatives');state.cache.cooperatives=d.items||[];if(state.selectedCoop&&!state.cache.cooperatives.some(x=>x.id===state.selectedCoop)){state.selectedCoop='';localStorage.removeItem('lg_coop')}state.selectedCoopName=state.cache.cooperatives.find(x=>x.id===state.selectedCoop)?.name||'';sel.innerHTML=`<option value="">Todas as cooperativas</option>${state.cache.cooperatives.map(x=>`<option value="${x.id}" ${x.id===state.selectedCoop?'selected':''}>${esc(x.name)}</option>`).join('')}`;sel.classList.remove('hidden');sel.onchange=()=>{state.selectedCoop=sel.value;localStorage.setItem('lg_coop',state.selectedCoop);state.selectedCoopName=state.cache.cooperatives.find(x=>x.id===state.selectedCoop)?.name||'';navigate(state.page,false)}}
async function baseData(){const key=state.selectedCoop||state.user.cooperative_id||'all';if(state.cache.baseKey===key)return state.cache;const q=query(scopeParams());const [ests,drivers,contracts,shifts,bases]=await Promise.all([api(`/api/app/establishments${q}`),api(`/api/app/drivers${q}`),api(`/api/app/contracts${q}`),api(`/api/app/shift-templates${q}`),api('/api/app/tenant/bases').catch(()=>({items:[]}))]);Object.assign(state.cache,{baseKey:key,establishments:ests.items||[],drivers:drivers.items||[],contracts:contracts.items||[],shifts:shifts.items||[],bases:bases.items||[]});return state.cache}
async function removeEntity(url,message,refresh){if(!confirm(message))return;try{loading(true);await api(url,{method:'DELETE'});toast('Registro removido.');state.cache.baseKey='';await refresh()}catch(e){toast(e.message,'error')}finally{loading(false)}}
const pages={};
window.state=state;window.pages=pages;

pages.dashboard=async()=>{const q=query(scopeParams());const [d,on]=await Promise.all([api(`/api/app/dashboard${q}`),api(`/api/app/online-drivers${q}`)]);const x=d.data||{};let stats;if(state.user.role==='driver')stats=[{icon:'➜',value:x.active_deliveries||0,label:'Entregas ativas'},{icon:'✓',value:x.deliveries_today||0,label:'Entregas hoje'},{icon:'＄',value:money(x.balance_cents),label:'Saldo a receber'},{icon:'▦',value:x.schedules_week||0,label:'Escalas nos próximos 7 dias'}];else if(state.user.role==='establishment')stats=[{icon:'➜',value:x.active_deliveries||0,label:'Entregas ativas'},{icon:'✓',value:x.deliveries_today||0,label:'Entregas hoje'},{icon:'＄',value:money(x.month_charge_cents),label:'Total do mês'},{icon:'♟',value:x.drivers_today||0,label:'Cooperados hoje'}];else stats=[{icon:'◉',value:x.cooperatives||0,label:'Cooperativas ativas'},{icon:'▤',value:x.establishments||0,label:'Estabelecimentos'},{icon:'♟',value:x.drivers||0,label:'Cooperados'},{icon:'●',value:x.online_drivers||0,label:'Online agora'},{icon:'➜',value:x.deliveries_today||0,label:'Entregas hoje'},{icon:'⌛',value:x.active_deliveries||0,label:'Entregas em andamento'},{icon:'＄',value:money(x.month_charge_cents),label:'Faturamento do mês'}];const online=(on.items||[]).filter(i=>i.online);$('#page-content').innerHTML=cards(stats)+panel('Cooperados online agora',table([{label:'Cooperado',key:'name'},{label:'Cooperativa',key:'cooperative_name'},{label:'Telefone',key:'phone'},{label:'Veículo',render:r=>esc([r.vehicle_model,r.vehicle_plate].filter(Boolean).join(' • ')||'—')},{label:'Última atualização',render:r=>dateTime(r.location_updated_at||r.last_seen_at)},{label:'Situação',render:r=>badge(r.online?'active':'inactive')}],online),`<button class="btn primary" data-page="tracking">Abrir rastreamento</button>`);$('[data-page="tracking"]')?.addEventListener('click',()=>navigate('tracking'))};

pages.cooperatives=async()=>{const d=await api('/api/app/cooperatives');$('#page-content').innerHTML=panel('Cooperativas cadastradas',table([{label:'Nome',key:'name'},{label:'CNPJ',key:'cnpj'},{label:'E-mail',key:'email'},{label:'Telefone',key:'phone'},{label:'Status',render:r=>badge(r.status)}],d.items,r=>`<button class="table-action" data-edit-coop="${r.id}">Editar</button><button class="table-action" data-del-coop="${r.id}">Excluir</button>`),'<button class="btn primary" id="new-coop">Nova cooperativa</button>');$('#new-coop').onclick=()=>cooperativeForm();$$('[data-edit-coop]').forEach(b=>b.onclick=()=>cooperativeForm(d.items.find(x=>x.id===b.dataset.editCoop)));$$('[data-del-coop]').forEach(b=>b.onclick=()=>removeEntity(`/api/app/cooperatives/${b.dataset.delCoop}`,'Excluir essa cooperativa?',pages.cooperatives))};
function cooperativeForm(item={}){openModal(item.id?'Editar cooperativa':'Nova cooperativa',`<form id="coop-form" class="form-grid">${field('Nome da cooperativa','name',item.name,'text','required')}${field('Razão social','legal_name',item.legal_name)}${field('CNPJ','cnpj',item.cnpj)}${field('Telefone','phone',item.phone)}${field('E-mail','email',item.email,'email')}${field('Cor principal','primary_color',item.primary_color||'#721536','color')}${textarea('Endereço','address',item.address)}${item.id?'':`<div class="full notice">Crie também o primeiro administrador dessa cooperativa.</div>${field('Nome do administrador','admin_name','','text','required')}${field('E-mail do administrador','admin_email','','email','required')}${field('Senha do administrador','admin_password','','password','required minlength="8"')}`}${buttons()}</form>`);$('#coop-form').onsubmit=async e=>{e.preventDefault();const b=formObject(e.currentTarget);try{loading(true);if(item.id){await api(`/api/app/cooperatives/${item.id}`,{method:'PUT',body:b})}else{const created=await api('/api/app/cooperatives',{method:'POST',body:b});await api('/api/app/users',{method:'POST',body:{cooperative_id:created.item.id,name:b.admin_name,email:b.admin_email,password:b.admin_password,role:'cooperative_admin'}})}closeModal();toast('Cooperativa salva.');state.cache.baseKey='';await renderMasterFilter();pages.cooperatives()}catch(err){toast(err.message,'error')}finally{loading(false)}}}

pages.users=async()=>{const base=await baseData();const d=await api(`/api/app/users${query(scopeParams())}`);const tools='<button class="btn primary" id="new-base-attendant">Cadastrar atendente da Base</button><button class="btn" id="new-user">Novo acesso administrativo</button>';$('#page-content').innerHTML=panel('Usuários e acessos',`<div class="notice"><strong>Atendente da Base:</strong> selecione obrigatoriamente a Base. Assim o usuário entra diretamente no painel operacional da Base e não acessa as demais Bases.</div>`+table([{label:'Nome',key:'name'},{label:'E-mail',key:'email'},{label:'Perfil',render:r=>esc(roles[r.role]||r.role)},{label:'Cooperativa',key:'cooperative_name'},{label:'Vínculo',render:r=>esc(r.base_name||r.establishment_name||r.driver_name||(r.role==='dispatcher'?'Sem Base vinculada':'—'))},{label:'Status',render:r=>badge(r.status)}],d.items,r=>r.role==='platform_admin'?'<span class="muted">Acesso Master protegido</span>':`<button class="table-action" data-edit-user="${r.id}">Editar</button><button class="table-action" data-del-user="${r.id}">Excluir</button>`),tools);$('#new-user').onclick=()=>userForm({},base,false);$('#new-base-attendant').onclick=()=>userForm({role:'dispatcher'},base,true);$$('[data-edit-user]').forEach(b=>b.onclick=()=>userForm(d.items.find(x=>x.id===b.dataset.editUser),base,d.items.find(x=>x.id===b.dataset.editUser)?.role==='dispatcher'));$$('[data-del-user]').forEach(b=>b.onclick=()=>removeEntity(`/api/app/users/${b.dataset.delUser}`,'Excluir este acesso?',pages.users))};
function userForm(item={},base=state.cache,attendantMode=false){const profileOptions=(attendantMode?['dispatcher']:['cooperative_admin','establishment','driver']).map(r=>`<option value="${r}" ${item.role===r?'selected':''}>${roles[r]}</option>`).join('');openModal(item.id?'Editar usuário':attendantMode?'Cadastrar atendente da Base':'Novo usuário',`<form id="user-form" class="form-grid">${attendantMode?'<div class="full notice"><strong>Acesso da Base</strong><br>O atendente poderá operar somente a Base selecionada. O sistema registra o nome dele nos atendimentos.</div>':''}${field('Nome','name',item.name,'text','required')}${field('E-mail','email',item.email,'email','required')}${field('Usuário opcional','username',item.username)}<label>Perfil<select name="role" required><option value="">Selecione</option>${profileOptions}</select></label>${selectField('Base do atendente','base_id',base.bases||[],item.base_id,'Selecione a Base',attendantMode||item.role==='dispatcher'?'required':'')}${selectField('Estabelecimento (perfil estabelecimento)','establishment_id',base.establishments||[],item.establishment_id,'Nenhum')}${selectField('Cooperado (perfil cooperado)','driver_id',base.drivers||[],item.driver_id,'Nenhum')}${item.id?'':field('Senha inicial','password','','password','required minlength="8"')}${item.id?field('Nova senha (opcional)','password','','password','minlength="8"'):''}<label>Status<select name="status"><option value="active">Ativo</option><option value="blocked" ${item.status==='blocked'?'selected':''}>Bloqueado</option><option value="inactive" ${item.status==='inactive'?'selected':''}>Inativo</option></select></label>${buttons(attendantMode?'Cadastrar atendente':'Salvar')}</form>`);$('#user-form').onsubmit=async e=>{e.preventDefault();const b=scopeBody(formObject(e.currentTarget));try{loading(true);await api(`/api/app/users${item.id?`/${item.id}`:''}`,{method:item.id?'PUT':'POST',body:b});closeModal();toast(attendantMode?'Atendente da Base salvo.':'Usuário salvo.');state.cache.baseKey='';pages.users()}catch(err){toast(err.message,'error')}finally{loading(false)}}}

pages.establishments=async()=>{const d=await api(`/api/app/establishments${query(scopeParams())}`);$('#page-content').innerHTML=panel('Estabelecimentos da cooperativa',table([{label:'Nome',key:'name'},{label:'CNPJ',key:'cnpj'},{label:'Telefone',key:'phone'},{label:'Endereço',key:'address',wrap:true},{label:'Acesso',render:r=>r.access_email?`<strong>${esc(r.access_email)}</strong><br>${badge(r.access_status||'active')}`:'<span class="muted">Sem acesso</span>'},{label:'Status',render:r=>badge(r.active?'active':'inactive')}],d.items,r=>canEdit()?`<button class="table-action" data-qr-est="${r.id}">QR</button><button class="table-action" data-access-est="${r.id}">Acesso</button><button class="table-action" data-edit-est="${r.id}">Editar</button><button class="table-action" data-del-est="${r.id}">Excluir</button>`:''),canEdit()?'<button class="btn primary" id="new-est">Novo estabelecimento</button>':'');if(canEdit()){$('#new-est').onclick=()=>establishmentForm();$$('[data-edit-est]').forEach(b=>b.onclick=()=>establishmentForm(d.items.find(x=>x.id===b.dataset.editEst)));$$('[data-access-est]').forEach(b=>b.onclick=()=>linkedAccessForm('establishment',d.items.find(x=>x.id===b.dataset.accessEst)));$$('[data-qr-est]').forEach(b=>b.onclick=()=>showEstablishmentQr(d.items.find(x=>x.id===b.dataset.qrEst)));$$('[data-del-est]').forEach(b=>b.onclick=()=>removeEntity(`/api/app/establishments/${b.dataset.delEst}`,'Excluir este estabelecimento?',pages.establishments))}};
function canEdit(){return ['platform_admin','cooperative_admin'].includes(state.user.role)}
function establishmentForm(item={}){openModal(item.id?'Editar estabelecimento':'Novo estabelecimento',`<form id="est-form" class="form-grid">${field('Nome fantasia','name',item.name,'text','required')}${field('Razão social','legal_name',item.legal_name)}${field('CNPJ','cnpj',item.cnpj)}${field('Telefone','phone',item.phone)}${field('E-mail comercial','email',item.email,'email')}${textarea('Endereço padrão de coleta','address',item.address,'required')}${item.id?'':`<div class="full notice"><strong>Acesso do restaurante</strong><br>Cadastre e-mail e senha para o estabelecimento entrar e criar ou acompanhar entregas.</div>${field('E-mail de acesso','access_email',item.email,'email')}${field('Senha inicial','access_password','','password','minlength="8"')}`}${buttons()}</form>`);$('#est-form').onsubmit=async e=>{e.preventDefault();const b=scopeBody(formObject(e.currentTarget));try{loading(true);let establishmentId=item.id;if(item.id)await api(`/api/app/establishments/${item.id}`,{method:'PUT',body:b});else{const d=await api('/api/app/establishments',{method:'POST',body:b});establishmentId=d.item.id;if(b.access_email&&b.access_password)await api(`/api/app/establishments/${establishmentId}/access`,{method:'POST',body:{name:b.name,email:b.access_email,password:b.access_password}})}closeModal();toast('Estabelecimento salvo.');state.cache.baseKey='';pages.establishments()}catch(err){toast(err.message,'error')}finally{loading(false)}}}
function linkedAccessForm(kind,item){const label=kind==='driver'?'cooperado':'estabelecimento';openModal(`Acesso do ${label}`,`<form id="linked-access-form" class="form-grid">${field('Nome do acesso','name',item.name,'text','required')}${field('E-mail para entrar','email',item.access_email||item.email,'email','required')}${field('Usuário opcional','username','')}${field(item.access_user_id?'Nova senha (opcional)':'Senha inicial','password','','password',item.access_user_id?'minlength="8"':'required minlength="8"')}<div class="full notice">Esse acesso verá somente os dados vinculados à própria cooperativa e ao próprio cadastro.</div>${buttons('Salvar acesso')}</form>`);$('#linked-access-form').onsubmit=async e=>{e.preventDefault();try{loading(true);await api(`/api/app/${kind==='driver'?'drivers':'establishments'}/${item.id}/access`,{method:'POST',body:formObject(e.currentTarget)});closeModal();toast('Acesso salvo.');kind==='driver'?pages.drivers():pages.establishments()}catch(err){toast(err.message,'error')}finally{loading(false)}}}
function showEstablishmentQr(item){const qr=qrcode(0,'M');qr.addData(item.checkin_token);qr.make();const svg=qr.createSvgTag(7,4);openModal(`QR Code — ${item.name}`,`<div class="qr-wrap"><p>O cooperado lê este QR ao chegar para fazer <strong>check-in</strong> e lê novamente ao sair para fazer <strong>check-out</strong>.</p><div id="est-qr-svg">${svg}</div><div class="code-box">${esc(item.checkin_token)}</div><div class="form-actions"><button class="btn" id="copy-qr-token">Copiar código</button><button class="btn primary" id="print-qr">Imprimir QR</button></div></div>`);$('#copy-qr-token').onclick=()=>navigator.clipboard.writeText(item.checkin_token).then(()=>toast('Código copiado.'));$('#print-qr').onclick=()=>{const w=open('','_blank','width=500,height=650');w.document.write(`<html><head><title>QR ${esc(item.name)}</title><style>body{font-family:Arial;text-align:center;padding:30px}svg{max-width:360px;height:auto}h1{color:#721536}</style></head><body><h1>ChegaJá</h1><h2>${esc(item.name)}</h2>${svg}<p>Leia para check-in e check-out.</p></body></html>`);w.document.close();w.print()}}

pages.drivers=async()=>{const d=await api(`/api/app/drivers${query(scopeParams())}`);$('#page-content').innerHTML=panel('Cooperados da cooperativa',table([{label:'Nome',key:'name'},{label:'CPF',key:'cpf'},{label:'Telefone',key:'phone'},{label:'Moto/placa',render:r=>esc([r.vehicle_model,r.vehicle_plate].filter(Boolean).join(' • ')||'—')},{label:'Acesso ao app',render:r=>r.access_email?`<strong>${esc(r.access_email)}</strong><br>${badge(r.access_status||'active')}`:'<span class="muted">Sem acesso</span>'},{label:'Online',render:r=>badge(r.online?'active':'inactive')},{label:'Status',render:r=>badge(r.status)}],d.items,r=>canEdit()?`<button class="table-action" data-access-driver="${r.id}">Acesso</button><button class="table-action" data-edit-driver="${r.id}">Editar</button><button class="table-action" data-del-driver="${r.id}">Excluir</button>`:''),canEdit()?'<button class="btn primary" id="new-driver">Novo cooperado</button>':'');if(canEdit()){$('#new-driver').onclick=()=>driverForm();$$('[data-edit-driver]').forEach(b=>b.onclick=()=>driverForm(d.items.find(x=>x.id===b.dataset.editDriver)));$$('[data-access-driver]').forEach(b=>b.onclick=()=>linkedAccessForm('driver',d.items.find(x=>x.id===b.dataset.accessDriver)));$$('[data-del-driver]').forEach(b=>b.onclick=()=>removeEntity(`/api/app/drivers/${b.dataset.delDriver}`,'Excluir este cooperado?',pages.drivers))}};
function driverForm(item={}){openModal(item.id?'Editar cooperado':'Novo cooperado',`<form id="driver-form" class="form-grid">${field('Nome','name',item.name,'text','required')}${field('CPF','cpf',item.cpf)}${field('Telefone','phone',item.phone)}${field('E-mail','email',item.email,'email')}${field('Placa','vehicle_plate',item.vehicle_plate)}${field('Modelo da moto','vehicle_model',item.vehicle_model)}${item.id?'':`<div class="full notice"><strong>Acesso ao aplicativo do cooperado</strong><br>Cadastre e-mail e senha para ele ver escalas, entregas, ganhos, ficar online e ler o QR.</div>${field('E-mail de acesso','access_email',item.email,'email')}${field('Senha inicial','access_password','','password','minlength="8"')}`}${buttons()}</form>`);$('#driver-form').onsubmit=async e=>{e.preventDefault();const b=scopeBody(formObject(e.currentTarget));try{loading(true);let driverId=item.id;if(item.id)await api(`/api/app/drivers/${item.id}`,{method:'PUT',body:b});else{const d=await api('/api/app/drivers',{method:'POST',body:b});driverId=d.item.id;if(b.access_email&&b.access_password)await api(`/api/app/drivers/${driverId}/access`,{method:'POST',body:{name:b.name,email:b.access_email,password:b.access_password}})}closeModal();toast('Cooperado salvo.');state.cache.baseKey='';pages.drivers()}catch(err){toast(err.message,'error')}finally{loading(false)}}}

pages.contracts=async()=>{const base=await baseData();const d=await api(`/api/app/contracts${query(scopeParams())}`);$('#page-content').innerHTML=panel('Contratos da cooperativa',table([{label:'Contrato',key:'name'},{label:'Estabelecimento',key:'establishment_name'},{label:'Código',key:'code'},{label:'Endereço de coleta',key:'pickup_address',wrap:true},{label:'Bairros cadastrados',key:'price_count'},{label:'Escalas',key:'schedule_count'},{label:'Status',render:r=>badge(r.active?'active':'inactive')}],d.items,r=>canEdit()?`<button class="table-action" data-edit-contract="${r.id}">Editar</button><button class="table-action" data-prices-contract="${r.id}">Valores</button><button class="table-action" data-del-contract="${r.id}">Excluir</button>`:''),canEdit()?'<button class="btn primary" id="new-contract">Novo contrato</button>':'');if(canEdit()){$('#new-contract').onclick=()=>contractForm({},base);$$('[data-edit-contract]').forEach(b=>b.onclick=()=>contractForm(d.items.find(x=>x.id===b.dataset.editContract),base));$$('[data-prices-contract]').forEach(b=>b.onclick=()=>{state.cache.priceContract=b.dataset.pricesContract;navigate('prices')});$$('[data-del-contract]').forEach(b=>b.onclick=()=>removeEntity(`/api/app/contracts/${b.dataset.delContract}`,'Excluir este contrato?',pages.contracts))}};
function contractForm(item={},base=state.cache){openModal(item.id?'Editar contrato':'Novo contrato',`<form id="contract-form" class="form-grid">${field('Nome do contrato','name',item.name,'text','required')}${field('Código opcional','code',item.code)}${selectField('Estabelecimento','establishment_id',base.establishments||[],item.establishment_id,'Sem vínculo')}${field('Endereço padrão de coleta','pickup_address',item.pickup_address)}${textarea('Observações','notes',item.notes)}${buttons()}</form>`);$('#contract-form').onsubmit=async e=>{e.preventDefault();try{loading(true);await api(`/api/app/contracts${item.id?`/${item.id}`:''}`,{method:item.id?'PUT':'POST',body:scopeBody(formObject(e.currentTarget))});closeModal();toast('Contrato salvo.');state.cache.baseKey='';pages.contracts()}catch(err){toast(err.message,'error')}finally{loading(false)}}}

pages.shifts=async()=>{const d=await api(`/api/app/shift-templates${query(scopeParams())}`);$('#page-content').innerHTML=panel('Horários fixos para usar nas escalas',table([{label:'Nome',key:'name'},{label:'Início',key:'start_time'},{label:'Fim',key:'end_time'},{label:'Turno',key:'shift_label'},{label:'Status',render:r=>badge(r.active?'active':'inactive')}],d.items,r=>canEdit()?`<button class="table-action" data-edit-shift="${r.id}">Editar</button><button class="table-action" data-del-shift="${r.id}">Excluir</button>`:''),canEdit()?'<button class="btn primary" id="new-shift">Novo horário fixo</button>':'');if(canEdit()){$('#new-shift').onclick=()=>shiftForm();$$('[data-edit-shift]').forEach(b=>b.onclick=()=>shiftForm(d.items.find(x=>x.id===b.dataset.editShift)));$$('[data-del-shift]').forEach(b=>b.onclick=()=>removeEntity(`/api/app/shift-templates/${b.dataset.delShift}`,'Excluir este horário?',pages.shifts))}};
function shiftForm(item={}){openModal(item.id?'Editar horário fixo':'Novo horário fixo',`<form id="shift-form" class="form-grid">${field('Nome do horário','name',item.name,'text','required placeholder="Ex.: 08h às 17h"')}${field('Turno','shift_label',item.shift_label,'text','required placeholder="Ex.: Diurno"')}${field('Hora inicial','start_time',item.start_time,'time','required')}${field('Hora final','end_time',item.end_time,'time','required')}${buttons()}</form>`);$('#shift-form').onsubmit=async e=>{e.preventDefault();try{loading(true);await api(`/api/app/shift-templates${item.id?`/${item.id}`:''}`,{method:item.id?'PUT':'POST',body:scopeBody(formObject(e.currentTarget))});closeModal();toast('Horário salvo.');state.cache.baseKey='';pages.shifts()}catch(err){toast(err.message,'error')}finally{loading(false)}}}

pages.schedules=async()=>{const base=await baseData();const mode=state.cache.scheduleMode||'week',ref=state.cache.scheduleRef||isoDate();let from,to;if(mode==='month')[from,to]=monthBounds(ref);else{from=mondayOf(ref);to=addDays(from,6)}const filters={...scopeParams(),from,to,driver_id:state.cache.scheduleDriver||'',contract_id:state.cache.scheduleContract||''};const d=await api(`/api/app/schedule-planner${query(filters)}`);const tools=`<div class="toolbar"><select id="schedule-mode"><option value="week" ${mode==='week'?'selected':''}>Semana</option><option value="month" ${mode==='month'?'selected':''}>Mês</option></select><input id="schedule-ref" type="date" value="${ref}"><select id="schedule-driver"><option value="">Todos os cooperados</option>${base.drivers.map(x=>`<option value="${x.id}" ${x.id===state.cache.scheduleDriver?'selected':''}>${esc(x.name)}</option>`).join('')}</select><select id="schedule-contract"><option value="">Todos os contratos</option>${base.contracts.map(x=>`<option value="${x.id}" ${x.id===state.cache.scheduleContract?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${['platform_admin','cooperative_admin','dispatcher'].includes(state.user.role)?'<button class="btn primary" id="new-schedule">Nova escala</button>':''}</div>`;let calendar='';if(mode==='week'){calendar=`<div class="calendar-list">${Array.from({length:7},(_,i)=>{const date=addDays(from,i),items=d.items.filter(x=>String(x.start_at).slice(0,10)===date);return `<div class="calendar-day"><h3>${['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'][i]} • ${dateOnly(date)}</h3>${items.map(x=>`<div class="schedule-chip"><strong>${esc(x.driver_name)}</strong><div>${timeOnly(x.start_at)}–${timeOnly(x.end_at)}</div><div>${esc(x.contract_name||'Sem contrato')}</div><div>${esc(x.shift_label||'')}</div></div>`).join('')||'<span class="muted">Sem escala</span>'}</div>`}).join('')}</div>`}const summary=panel('Contagem por cooperado e contrato',table([{label:'Cooperado',key:'driver_name'},{label:'Contrato',key:'contract_name'},{label:'Quantidade no período',key:'count'}],d.summary));const list=table([{label:'Data',render:r=>dateOnly(String(r.start_at).slice(0,10))},{label:'Cooperado',key:'driver_name'},{label:'Horário',render:r=>`${timeOnly(r.start_at)} às ${timeOnly(r.end_at)}`},{label:'Contrato',key:'contract_name'},{label:'Turno',key:'shift_label'},{label:'Estabelecimento',key:'establishment_name'},{label:'Status',render:r=>badge(r.status)}],d.items,r=>['platform_admin','cooperative_admin','dispatcher'].includes(state.user.role)?`<button class="table-action" data-edit-schedule="${r.id}">Editar</button><button class="table-action" data-del-schedule="${r.id}">Excluir</button>`:'');$('#page-content').innerHTML=panel(`Escala de ${dateOnly(from)} até ${dateOnly(to)}`,calendar||list,tools)+(calendar?panel('Lista completa',list):'')+summary;$('#schedule-mode').onchange=e=>{state.cache.scheduleMode=e.target.value;pages.schedules()};$('#schedule-ref').onchange=e=>{state.cache.scheduleRef=e.target.value;pages.schedules()};$('#schedule-driver').onchange=e=>{state.cache.scheduleDriver=e.target.value;pages.schedules()};$('#schedule-contract').onchange=e=>{state.cache.scheduleContract=e.target.value;pages.schedules()};$('#new-schedule')?.addEventListener('click',()=>scheduleForm({},base));$$('[data-edit-schedule]').forEach(b=>b.onclick=()=>scheduleForm(d.items.find(x=>x.id===b.dataset.editSchedule),base));$$('[data-del-schedule]').forEach(b=>b.onclick=async()=>{const scope=confirm('OK: excluir apenas esta escala.\nCancelar: escolher outra opção.')?'one':'one';await removeEntity(`/api/app/schedule-planner/${b.dataset.delSchedule}`,'Confirma excluir esta escala?',pages.schedules)})};
function scheduleForm(item={},base=state.cache){const isEdit=Boolean(item.id),date=String(item.start_at||isoDate()).slice(0,10),start=timeOnly(item.start_at),end=timeOnly(item.end_at);openModal(isEdit?'Editar escala':'Nova escala',`<form id="schedule-form" class="form-grid">${selectField('Cooperado','driver_id',base.drivers||[],item.driver_id,'Selecione','required')}${selectField('Contrato','contract_id',base.contracts||[],item.contract_id,'Sem contrato')}${!isEdit?selectField('Horário fixo','shift_template_id',base.shifts||[],item.shift_template_id,'Usar horário manual'):''}${field(isEdit?'Data':'Data inicial','start_date',date,'date','required')}${!isEdit?field('Data final','end_date',date,'date','required'):''}${field('Hora inicial','start_time',start==='—'?'':start,'time')}${field('Hora final','end_time',end==='—'?'':end,'time')}${field('Turno','shift_label',item.shift_label||'')}${field('Valor garantido','guaranteed_value',Number(item.guaranteed_cents||0)/100,'number','step="0.01" min="0"')}${!isEdit?`<div class="full"><strong>Dias da semana</strong><div class="weekday-grid">${[['1','Seg'],['2','Ter'],['3','Qua'],['4','Qui'],['5','Sex'],['6','Sáb'],['0','Dom']].map(([v,l],i)=>`<label class="check-card"><input type="checkbox" name="weekdays[]" value="${v}" ${i<5?'checked':''}><span>${l}</span></label>`).join('')}</div></div>`:''}${textarea('Observações','notes',item.notes)}${buttons()}</form>`);$('#schedule-form').onsubmit=async e=>{e.preventDefault();let b=scopeBody(formObject(e.currentTarget));if(isEdit){b.date=b.start_date;delete b.start_date;delete b.end_date}const send=async allow=>api(`/api/app/schedule-planner${isEdit?`/${item.id}`:''}`,{method:isEdit?'PUT':'POST',body:{...b,allow_conflict:allow}});try{loading(true);await send(false);closeModal();toast('Escala salva.');pages.schedules()}catch(err){if(err.data?.conflict&&confirm(`${err.message}\n\nDeseja salvar mesmo com conflito?`)){try{await send(true);closeModal();toast('Escala salva com alerta de conflito.');pages.schedules()}catch(e2){toast(e2.message,'error')}}else toast(err.message,'error')}finally{loading(false)}}}

pages.deliveries=async()=>{const base=await baseData();const d=await api(`/api/app/deliveries-v2${query(scopeParams({status:state.cache.deliveryStatus||''}))}`);const tools=`<div class="toolbar"><select id="delivery-status"><option value="">Todos os status</option>${['new','assigned','accepted','to_pickup','at_pickup','picked_up','in_route','delivered','cancelled','problem'].map(s=>`<option value="${s}" ${state.cache.deliveryStatus===s?'selected':''}>${statusText[s]}</option>`).join('')}</select>${state.user.role!=='driver'?'<button class="btn primary" id="new-delivery">Nova entrega</button>':''}</div>`;$('#page-content').innerHTML=panel('Entregas',table([{label:'Data',render:r=>dateTime(r.created_at)},{label:'Cliente',render:r=>`<strong>${esc(r.customer_name)}</strong><br><small>${esc(r.customer_phone)}</small>`},{label:'Coleta',render:r=>`<strong>${esc(r.pickup_address)}</strong><br><small>${esc(r.pickup_neighborhood||'')}</small>`,wrap:true},{label:'Entrega',render:r=>`<strong>${esc(r.delivery_address)}</strong><br><small>${esc(r.delivery_neighborhood||'')}</small>`,wrap:true},{label:'Contrato',key:'contract_name'},{label:'Cooperado',key:'driver_name'},{label:'Valor',render:r=>money(r.charge_cents)},{label:'Status',render:r=>badge(r.status)}],d.items,r=>deliveryActions(r,base)),tools);$('#delivery-status').onchange=e=>{state.cache.deliveryStatus=e.target.value;pages.deliveries()};$('#new-delivery')?.addEventListener('click',()=>deliveryForm({},base));bindDeliveryActions(d.items,base)};
function deliveryActions(r,base){let a=`<button class="table-action" data-detail-delivery="${r.id}">Ver</button>`;if(['platform_admin','cooperative_admin','dispatcher','establishment'].includes(state.user.role)&&!['delivered','cancelled'].includes(r.status)){a+=`<button class="table-action" data-edit-delivery="${r.id}">Editar</button><button class="table-action" data-assign-delivery="${r.id}">Atribuir</button>`}if(state.user.role==='driver'){const next={assigned:'accepted',accepted:'to_pickup',to_pickup:'at_pickup',at_pickup:'picked_up',picked_up:'in_route',in_route:'delivered'}[r.status];if(next)a+=`<button class="table-action" data-status-delivery="${r.id}" data-status="${next}">${statusText[next]}</button>`}if(['platform_admin','cooperative_admin','dispatcher'].includes(state.user.role)&&!['delivered','cancelled'].includes(r.status))a+=`<button class="table-action" data-status-delivery="${r.id}" data-status="cancelled">Cancelar</button>`;return a}
function bindDeliveryActions(items,base){$$('[data-detail-delivery]').forEach(b=>b.onclick=()=>deliveryDetail(items.find(x=>x.id===b.dataset.detailDelivery)));$$('[data-edit-delivery]').forEach(b=>b.onclick=()=>deliveryForm(items.find(x=>x.id===b.dataset.editDelivery),base));$$('[data-assign-delivery]').forEach(b=>b.onclick=()=>assignDelivery(items.find(x=>x.id===b.dataset.assignDelivery),base));$$('[data-status-delivery]').forEach(b=>b.onclick=async()=>{try{loading(true);await api(`/api/app/deliveries/${b.dataset.statusDelivery}/status`,{method:'POST',body:{status:b.dataset.status}});toast('Status atualizado.');pages.deliveries()}catch(e){toast(e.message,'error')}finally{loading(false)}})}
function deliveryDetail(r){openModal('Detalhes da entrega',`<div class="detail-grid"><div><small>Cliente</small><strong>${esc(r.customer_name)}</strong><p>${esc(r.customer_phone)}</p></div><div><small>Contrato</small><strong>${esc(r.contract_name||'Sem contrato')}</strong><p>${esc(r.establishment_name)}</p></div><div class="full"><small>Coleta</small><strong>${esc(r.pickup_address)}</strong><p>${esc(r.pickup_contact_name||'')} ${esc(r.pickup_phone||'')}</p></div><div class="full"><small>Entrega</small><strong>${esc(r.delivery_address)}</strong><p>${esc(r.recipient_name||'')} ${esc(r.recipient_phone||'')}</p></div><div><small>Valor</small><strong>${money(r.charge_cents)}</strong><p>Cooperado: ${money(r.driver_earnings_cents)}</p></div><div><small>Status</small><strong>${statusText[r.status]||r.status}</strong><p>${esc(r.payment_method||'')}</p></div><div class="full"><small>Item/observações</small><p>${esc(r.item_description||'—')}<br>${esc(r.notes||'')}</p></div></div><div class="form-actions"><button class="btn primary" id="copy-track">Copiar link de rastreio</button></div>`);$('#copy-track').onclick=()=>navigator.clipboard.writeText(`${location.origin}/r/${r.tracking_token}`).then(()=>toast('Link copiado.'))}
function deliveryForm(item={},base=state.cache){const establishmentId=state.user.role==='establishment'?state.user.establishment_id:item.establishment_id;const est=base.establishments.find(x=>x.id===establishmentId);openModal(item.id?'Editar entrega':'Nova entrega',`<form id="delivery-form" class="form-grid">${state.user.role==='establishment'?`<input type="hidden" name="establishment_id" value="${esc(establishmentId)}">`:selectField('Estabelecimento','establishment_id',base.establishments||[],establishmentId,'Selecione','required')}${selectField('Contrato','contract_id',base.contracts||[],item.contract_id,'Sem contrato')}${field('Número do pedido','external_id',item.external_id)}${field('Nome do cliente','customer_name',item.customer_name,'text','required')}${field('Telefone do cliente','customer_phone',item.customer_phone,'tel','required')}${field('Pessoa na coleta','pickup_contact_name',item.pickup_contact_name)}${field('Telefone da coleta','pickup_phone',item.pickup_phone,'tel')}${field('Bairro da coleta','pickup_neighborhood',item.pickup_neighborhood)}${field('Endereço de coleta','pickup_address',item.pickup_address||est?.address,'text','required')}${field('Quem recebe','recipient_name',item.recipient_name)}${field('Telefone de quem recebe','recipient_phone',item.recipient_phone,'tel')}${field('Bairro da entrega','delivery_neighborhood',item.delivery_neighborhood)}${field('Endereço de entrega','delivery_address',item.delivery_address,'text','required')}${field('Valor cobrado','charge_value',Number(item.charge_cents||0)/100,'number','step="0.01" min="0"')}${field('Valor do cooperado','driver_value',Number(item.driver_earnings_cents||0)/100,'number','step="0.01" min="0"')}${field('Taxa da cooperativa','cooperative_value',Number(item.cooperative_fee_cents||0)/100,'number','step="0.01" min="0"')}<label>Pagamento<select name="payment_method"><option value="pix">PIX</option><option value="dinheiro" ${item.payment_method==='dinheiro'?'selected':''}>Dinheiro</option><option value="pix_cooperativa" ${item.payment_method==='pix_cooperativa'?'selected':''}>PIX Cooperativa</option><option value="credit" ${['credit','credito'].includes(item.payment_method)?'selected':''}>Crédito antecipado</option></select></label>${selectField('Atribuir cooperado','assigned_driver_id',base.drivers||[],item.assigned_driver_id,'Depois')}${textarea('Descrição do item','item_description',item.item_description)}${textarea('Observações','notes',item.notes)}${buttons()}</form>`);$('#delivery-form').onsubmit=async e=>{e.preventDefault();try{loading(true);await api(`/api/app/deliveries-v2${item.id?`/${item.id}`:''}`,{method:item.id?'PUT':'POST',body:scopeBody(formObject(e.currentTarget))});closeModal();toast('Entrega salva.');pages.deliveries()}catch(err){toast(err.message,'error')}finally{loading(false)}}}
function assignDelivery(item,base){openModal('Atribuir cooperado',`<form id="assign-form" class="form-grid">${selectField('Cooperado','driver_id',base.drivers||[],item.assigned_driver_id,'Selecione','required')}${buttons('Atribuir')}</form>`);$('#assign-form').onsubmit=async e=>{e.preventDefault();try{loading(true);await api(`/api/app/deliveries/${item.id}/assign`,{method:'POST',body:formObject(e.currentTarget)});closeModal();toast('Cooperado atribuído.');pages.deliveries()}catch(err){toast(err.message,'error')}finally{loading(false)}}}

pages.customerRequests=async()=>{const base=await baseData();const d=await api(`/api/app/customer-requests${query(scopeParams())}`);$('#page-content').innerHTML=panel('Solicitações feitas pelo aplicativo de clientes',table([{label:'Data',render:r=>dateTime(r.created_at)},{label:'Cliente',render:r=>`<strong>${esc(r.customer_name)}</strong><br>${esc(r.customer_phone)}`},{label:'Coleta',key:'pickup_address',wrap:true},{label:'Entrega',key:'delivery_address',wrap:true},{label:'Valor estimado',render:r=>money(r.quoted_cents)},{label:'Status',render:r=>badge(r.status)}],d.items,r=>r.status==='new'?`<button class="table-action" data-convert-request="${r.id}">Transformar em entrega</button>`:`<span class="muted">${esc(r.delivery_status||'')}</span>`));$$('[data-convert-request]').forEach(b=>b.onclick=()=>convertRequest(d.items.find(x=>x.id===b.dataset.convertRequest),base))};
function convertRequest(item,base){openModal('Transformar solicitação em entrega',`<form id="convert-form" class="form-grid">${selectField('Estabelecimento','establishment_id',base.establishments||[],'','Selecione','required')}${selectField('Contrato','contract_id',base.contracts||[],'','Sem contrato')}${selectField('Cooperado','assigned_driver_id',base.drivers||[],'','Atribuir depois')}${buttons('Criar entrega')}</form>`);$('#convert-form').onsubmit=async e=>{e.preventDefault();try{loading(true);const d=await api(`/api/app/customer-requests/${item.id}/convert`,{method:'POST',body:formObject(e.currentTarget)});closeModal();toast('Entrega criada.');navigator.clipboard?.writeText(d.tracking_url);pages.customerRequests()}catch(err){toast(err.message,'error')}finally{loading(false)}}}



function durationText(minutes){const n=Math.max(0,Number(minutes||0));const h=Math.floor(n/60),m=n%60;return h?`${h}h ${m}min`:`${m}min`}
pages.attendance=async()=>{const base=await baseData();const filters=scopeParams({from:state.cache.attFrom||addDays(isoDate(),-7),to:state.cache.attTo||isoDate(),driver_id:state.cache.attDriver||'',establishment_id:state.cache.attEst||''});const d=await api(`/api/app/checkins${query(filters)}`);let current=null;if(state.user.role==='driver'){const c=await api('/api/app/attendance/current');current=c.item}const tools=state.user.role==='driver'?'<button class="btn primary" id="scan-attendance">Ler QR Code</button>':`<div class="toolbar"><input id="att-from" type="date" value="${esc(filters.from)}"><input id="att-to" type="date" value="${esc(filters.to)}"><select id="att-driver"><option value="">Todos os cooperados</option>${(base.drivers||[]).map(x=>`<option value="${x.id}" ${x.id===state.cache.attDriver?'selected':''}>${esc(x.name)}</option>`).join('')}</select><select id="att-est"><option value="">Todos os estabelecimentos</option>${(base.establishments||[]).map(x=>`<option value="${x.id}" ${x.id===state.cache.attEst?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${state.user.role==='establishment'?'<button class="btn primary" id="show-own-qr">Mostrar meu QR</button>':''}</div>`;const currentBox=state.user.role==='driver'?panel('Presença atual',current?`<div class="attendance-current"><div><small>Estabelecimento</small><strong>${esc(current.establishment_name)}</strong></div><div><small>Entrada</small><strong>${dateTime(current.checked_in_at)}</strong></div><div><small>Tempo no local</small><strong>${durationText(current.duration_minutes)}</strong></div><div><small>Saída</small><strong>Leia novamente o mesmo QR</strong></div></div>`:empty('Nenhum check-in aberto','Ao chegar ao estabelecimento, toque em Ler QR Code.'),tools):'';$('#page-content').innerHTML=currentBox+panel(state.user.role==='driver'?'Meu histórico de check-in e check-out':'Check-in e check-out dos cooperados',table([{label:'Cooperado',key:'driver_name'},{label:'Estabelecimento',key:'establishment_name'},{label:'Contrato',key:'contract_name'},{label:'Check-in',render:r=>dateTime(r.checked_in_at)},{label:'Check-out',render:r=>r.checked_out_at?dateTime(r.checked_out_at):'<span class="positive">Em andamento</span>'},{label:'Tempo',render:r=>durationText(r.duration_minutes)},{label:'Origem',render:r=>r.source==='qr'?'QR Code':esc(r.source)}],d.items),state.user.role==='driver'?'':tools);$('#scan-attendance')?.addEventListener('click',openQrScanner);$('#show-own-qr')?.addEventListener('click',()=>showEstablishmentQr((base.establishments||[])[0]));const refresh=()=>{state.cache.attFrom=$('#att-from')?.value||filters.from;state.cache.attTo=$('#att-to')?.value||filters.to;state.cache.attDriver=$('#att-driver')?.value||'';state.cache.attEst=$('#att-est')?.value||'';pages.attendance()};$('#att-from')?.addEventListener('change',refresh);$('#att-to')?.addEventListener('change',refresh);$('#att-driver')?.addEventListener('change',refresh);$('#att-est')?.addEventListener('change',refresh)};
let qrStream=null,qrScanTimer=null,qrScanBusy=false;
function stopQrScanner(){if(qrScanTimer){clearInterval(qrScanTimer);qrScanTimer=null}if(qrStream){qrStream.getTracks().forEach(t=>t.stop());qrStream=null}qrScanBusy=false}
async function submitAttendanceToken(token){if(qrScanBusy||!String(token||'').trim())return;qrScanBusy=true;try{let latitude=null,longitude=null;try{const p=await currentPosition();latitude=p.coords.latitude;longitude=p.coords.longitude}catch{}const d=await api('/api/app/checkins',{method:'POST',body:{token:String(token).trim(),latitude,longitude}});stopQrScanner();closeModal();toast(d.action==='checkout'?`Check-out realizado em ${d.establishment}. Tempo: ${durationText(d.duration_minutes)}.`:`Check-in realizado em ${d.establishment}.`);pages.attendance()}catch(e){qrScanBusy=false;toast(e.message,'error')}}
async function openQrScanner(){openModal('Ler QR Code do estabelecimento',`<div class="scanner-box"><video id="qr-video" playsinline muted></video><div id="qr-help" class="notice">Aponte a câmera para o QR Code exposto no estabelecimento.</div><form id="manual-qr-form" class="form-grid"><div class="full notice">Caso a câmera não reconheça, digite o código impresso abaixo do QR.</div>${field('Código do QR','token','','text','required placeholder="CE-..."')}${buttons('Confirmar código')}</form></div>`);$('#manual-qr-form').onsubmit=e=>{e.preventDefault();submitAttendanceToken(formObject(e.currentTarget).token)};try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Câmera não disponível neste aparelho.');qrStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const video=$('#qr-video');video.srcObject=qrStream;await video.play();if(!('BarcodeDetector'in window)){throw new Error('Leitura automática não suportada neste navegador. Use o código abaixo do QR.')}const detector=new BarcodeDetector({formats:['qr_code']});qrScanTimer=setInterval(async()=>{if(qrScanBusy||video.readyState<2)return;try{const codes=await detector.detect(video);if(codes?.[0]?.rawValue)submitAttendanceToken(codes[0].rawValue)}catch{}},500)}catch(e){$('#qr-help').textContent=`${e.message} Digite o código manualmente.`}}

pages.tracking=async()=>{if(state.timer){clearInterval(state.timer);state.timer=null}const refreshTracking=async()=>{if(state.page!=='tracking')return;const d=await api(`/api/app/online-drivers${query(scopeParams())}`);$('#page-content').innerHTML=panel('Cooperados online da cooperativa',`<div id="live-map" class="map"></div>`)+panel('Lista de cooperados',table([{label:'Cooperado',key:'name'},{label:'Telefone',key:'phone'},{label:'Moto',render:r=>esc([r.vehicle_model,r.vehicle_plate].filter(Boolean).join(' • ')||'—')},{label:'Online',render:r=>badge(r.online?'active':'inactive')},{label:'Última atualização',render:r=>dateTime(r.location_updated_at||r.last_seen_at)}],d.items));if(state.map){try{state.map.remove()}catch{}state.map=null}state.map=L.map('live-map').setView([-5.7945,-35.211],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(state.map);const pts=[];(d.items||[]).filter(x=>x.online&&x.current_lat!=null&&x.current_lng!=null).forEach(x=>{L.marker([x.current_lat,x.current_lng]).addTo(state.map).bindPopup(`<strong>${esc(x.name)}</strong><br>${esc(x.vehicle_plate||'')}<br>${dateTime(x.location_updated_at)}`);pts.push([x.current_lat,x.current_lng])});if(pts.length)state.map.fitBounds(pts,{padding:[35,35],maxZoom:17})};await refreshTracking();state.timer=setInterval(()=>{if(state.page==='tracking'&&!document.hidden)refreshTracking().catch(()=>{})},6000)};

pages.prices=async()=>{const base=await baseData();const contractId=state.cache.priceContract||'';const d=await api(`/api/app/contract-prices${query(scopeParams({contract_id:contractId}))}`);const tools=`<div class="toolbar"><select id="price-contract"><option value="">Todos os contratos</option>${base.contracts.map(x=>`<option value="${x.id}" ${contractId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>${canEdit()?'<button class="btn primary" id="new-price">Novo bairro/valor</button>':''}</div>`;$('#page-content').innerHTML=panel('Tabela: contrato, bairro, valor fixo e valor base',table([{label:'Contrato',key:'contract_name'},{label:'Bairro',key:'neighborhood'},{label:'Valor fixo',render:r=>money(r.fixed_cents)},{label:'Valor base',render:r=>money(r.base_cents)},{label:'Valor cooperado',render:r=>money(r.driver_cents)},{label:'Taxa cooperativa',render:r=>money(r.cooperative_cents)}],d.items,r=>canEdit()?`<button class="table-action" data-edit-price="${r.id}">Editar</button><button class="table-action" data-del-price="${r.id}">Excluir</button>`:''),tools);$('#price-contract').onchange=e=>{state.cache.priceContract=e.target.value;pages.prices()};if(canEdit()){$('#new-price').onclick=()=>priceForm({},base);$$('[data-edit-price]').forEach(b=>b.onclick=()=>priceForm(d.items.find(x=>x.id===b.dataset.editPrice),base));$$('[data-del-price]').forEach(b=>b.onclick=()=>removeEntity(`/api/app/contract-prices/${b.dataset.delPrice}`,'Excluir esse valor?',pages.prices))}};
function priceForm(item={},base=state.cache){openModal(item.id?'Editar valor':'Novo bairro e valor',`<form id="price-form" class="form-grid">${item.id?`<input type="hidden" name="contract_id" value="${esc(item.contract_id)}">`:selectField('Contrato','contract_id',base.contracts||[],state.cache.priceContract,'Selecione','required')}${field('Bairro','neighborhood',item.neighborhood,'text','required')}${field('Valor fixo','fixed_value',Number(item.fixed_cents||0)/100,'number','step="0.01" min="0"')}${field('Valor base','base_value',Number(item.base_cents||0)/100,'number','step="0.01" min="0"')}${field('Valor do cooperado','driver_value',Number(item.driver_cents||0)/100,'number','step="0.01" min="0"')}${field('Taxa da cooperativa','cooperative_value',Number(item.cooperative_cents||0)/100,'number','step="0.01" min="0"')}${buttons()}</form>`);$('#price-form').onsubmit=async e=>{e.preventDefault();try{loading(true);await api(`/api/app/contract-prices${item.id?`/${item.id}`:''}`,{method:item.id?'PUT':'POST',body:formObject(e.currentTarget)});closeModal();toast('Valor salvo.');pages.prices()}catch(err){toast(err.message,'error')}finally{loading(false)}}}

pages.financial=async()=>{const base=await baseData();const params=scopeParams({driver_id:state.cache.financeDriver||''});const [d,s]=await Promise.all([api(`/api/app/financial${query(params)}`),api(`/api/app/financial/summary${query(params)}`)]);const x=s.data||{};const tools=`<div class="toolbar">${state.user.role!=='driver'?`<select id="finance-driver"><option value="">Todos os cooperados</option>${base.drivers.map(x=>`<option value="${x.id}" ${state.cache.financeDriver===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:''}${canEdit()?'<button class="btn primary" id="new-financial">Novo lançamento</button>':''}</div>`;$('#page-content').innerHTML=cards([{icon:'＋',value:money(x.credits_cents),label:'Ganhos/créditos'},{icon:'−',value:money(x.debits_cents),label:'Descontos'},{icon:'＝',value:money(x.balance_cents),label:'Valor a receber'}])+panel('Lançamentos financeiros',table([{label:'Data',render:r=>dateOnly(r.reference_date)},{label:'Cooperado',key:'driver_name'},{label:'Tipo',render:r=>r.entry_type==='credit'?'<span class="positive">Crédito</span>':'<span class="negative">Desconto</span>'},{label:'Categoria',key:'category'},{label:'Descrição',key:'description',wrap:true},{label:'Valor',render:r=>money(r.amount_cents)},{label:'Status',render:r=>badge(r.status)}],d.items,r=>canEdit()?`<button class="table-action" data-del-financial="${r.id}">Cancelar</button>`:''),tools);$('#finance-driver')?.addEventListener('change',e=>{state.cache.financeDriver=e.target.value;pages.financial()});$('#new-financial')?.addEventListener('click',()=>financialForm(base));$$('[data-del-financial]').forEach(b=>b.onclick=()=>removeEntity(`/api/app/financial/${b.dataset.delFinancial}`,'Cancelar este lançamento?',pages.financial))};
function financialForm(base){openModal('Novo ganho ou desconto',`<form id="financial-form" class="form-grid">${selectField('Cooperado','driver_id',base.drivers||[],state.cache.financeDriver,'Selecione','required')}<label>Tipo<select name="entry_type"><option value="credit">Crédito / ganho</option><option value="debit">Desconto</option></select></label>${field('Categoria','category','adjustment','text','required')}${field('Valor','amount','','number','required step="0.01" min="0.01"')}${field('Data de referência','reference_date',isoDate(),'date','required')}${textarea('Descrição','description','','required')}${buttons()}</form>`);$('#financial-form').onsubmit=async e=>{e.preventDefault();try{loading(true);await api('/api/app/financial',{method:'POST',body:formObject(e.currentTarget)});closeModal();toast('Lançamento criado.');pages.financial()}catch(err){toast(err.message,'error')}finally{loading(false)}}}

pages.integrations=async()=>{const base=await baseData();const [keys,hooks]=await Promise.all([api(`/api/app/api-clients${query(scopeParams())}`),api(`/api/app/webhooks${query(scopeParams())}`)]);const endpoint=`${location.origin}/api/v1/orders`;const sample=`POST ${endpoint}\nX-API-Key: SUA_CHAVE\nContent-Type: application/json\n\n{\n  "external_id": "PEDIDO-123",\n  "source": "sistema_restaurante",\n  "customer_name": "Nome do cliente",\n  "customer_phone": "84999999999",\n  "recipient_name": "Nome de quem recebe",\n  "recipient_phone": "84999999999",\n  "delivery_address_json": {\n    "street": "Avenida Prudente de Morais",\n    "number": "1000",\n    "neighborhood": "Lagoa Nova",\n    "city": "Natal",\n    "state": "RN",\n    "postal_code": "59056-200"\n  },\n  "payment_method": "pix",\n  "notes": "Observações"\n}`;$('#page-content').innerHTML=panel('Como o sistema do restaurante envia pedidos',`<div class="notice"><strong>Entrada das entregas:</strong> o sistema do estabelecimento deve enviar cada pedido para a API abaixo usando a chave criada nesta tela. A entrega chegará automaticamente na cooperativa correta e ficará aguardando a atribuição do cooperado.</div><div class="code-box">${esc(sample)}</div><p class="muted">Não envie latitude, longitude nem endereço solto. Envie o destino em JSON com rua, número, cidade e estado, ou use o confirmation_token da busca de endereço. A coleta usa o endereço confirmado do estabelecimento.</p>`)+panel('Chaves de integração do estabelecimento',table([{label:'Nome',key:'name'},{label:'Estabelecimento',key:'establishment_name'},{label:'Prefixo',key:'key_prefix'},{label:'Último uso',render:r=>dateTime(r.last_used_at)},{label:'Status',render:r=>badge(r.status)}],keys.items,r=>r.status==='active'?`<button class="table-action" data-revoke-key="${r.id}">Revogar</button>`:''),'<button class="btn primary" id="new-key">Nova chave</button>')+panel('Webhook de retorno para o sistema do restaurante',table([{label:'Nome',key:'name'},{label:'Estabelecimento',key:'establishment_name'},{label:'URL do sistema',key:'url',wrap:true},{label:'Eventos',key:'events',wrap:true},{label:'Status',render:r=>badge(r.status)}],hooks.items,r=>`<button class="table-action" data-del-hook="${r.id}">Excluir</button>`),'<button class="btn primary" id="new-hook">Cadastrar URL do sistema</button>');$('#new-key').onclick=()=>integrationKeyForm(base);$('#new-hook').onclick=()=>webhookForm(base);$$('[data-revoke-key]').forEach(b=>b.onclick=async()=>{if(!confirm('Revogar esta chave?'))return;try{await api(`/api/app/api-clients/${b.dataset.revokeKey}/revoke`,{method:'POST'});pages.integrations()}catch(e){toast(e.message,'error')}});$$('[data-del-hook]').forEach(b=>b.onclick=()=>removeEntity(`/api/app/webhooks/${b.dataset.delHook}`,'Excluir este webhook?',pages.integrations))};
function integrationKeyForm(base){const estField=state.user.role==='establishment'?`<input type="hidden" name="establishment_id" value="${esc(state.user.establishment_id)}">`:selectField('Estabelecimento','establishment_id',base.establishments||[],'','Selecione','required');openModal('Nova chave de integração',`<form id="key-form" class="form-grid">${field('Nome da integração','name','Sistema do estabelecimento','text','required')}${estField}<div class="full notice">Esta chave permitirá que o sistema escolhido envie e consulte somente as entregas desse estabelecimento.</div>${buttons('Gerar chave')}</form>`);$('#key-form').onsubmit=async e=>{e.preventDefault();try{loading(true);const d=await api('/api/app/api-clients',{method:'POST',body:scopeBody(formObject(e.currentTarget))});openModal('Chave criada',`<div class="notice">Copie agora. Ela não será mostrada novamente.</div><div class="code-box">${esc(d.item.api_key)}</div><div class="form-actions"><button class="btn primary" id="copy-key">Copiar chave</button></div>`);$('#copy-key').onclick=()=>navigator.clipboard.writeText(d.item.api_key).then(()=>toast('Chave copiada.'))}catch(err){toast(err.message,'error')}finally{loading(false)}}}
function webhookForm(base){const estField=state.user.role==='establishment'?`<input type="hidden" name="establishment_id" value="${esc(state.user.establishment_id)}">`:selectField('Estabelecimento','establishment_id',base.establishments||[],'','Selecione','required');openModal('URL do sistema do estabelecimento',`<form id="hook-form" class="form-grid">${field('Nome','name','Retorno de status','text','required')}${estField}${field('URL HTTPS do sistema','url','','url','required placeholder="https://sistema-do-restaurante.com/webhook"')}${field('Eventos','events','delivery.created,delivery.assigned,delivery.status_changed','text','required')}<div class="full notice">O ChegaJá enviará atualizações para essa URL quando a entrega for criada, atribuída ou mudar de status.</div>${buttons('Cadastrar webhook')}</form>`);$('#hook-form').onsubmit=async e=>{e.preventDefault();try{loading(true);const d=await api('/api/app/webhooks',{method:'POST',body:scopeBody(formObject(e.currentTarget))});openModal('Webhook criado',`<div class="notice">Guarde este segredo para validar as mensagens recebidas.</div><div class="code-box">${esc(d.item.secret)}</div><div class="form-actions"><button class="btn primary" id="copy-hook-secret">Copiar segredo</button></div>`);$('#copy-hook-secret').onclick=()=>navigator.clipboard.writeText(d.item.secret).then(()=>toast('Segredo copiado.'))}catch(err){toast(err.message,'error')}finally{loading(false)}}}

pages.audit=async()=>{const d=await api(`/api/app/audit${query(scopeParams())}`);$('#page-content').innerHTML=panel(state.user.role==='platform_admin'?'Auditoria da plataforma':'Auditoria da sua cooperativa',table([{label:'Data',render:r=>dateTime(r.created_at)},{label:'Usuário',key:'user_name'},{label:'Ação',key:'action'},{label:'Tipo',key:'entity_type'},{label:'ID',render:r=>`<code>${esc(r.entity_id||'—')}</code>`},{label:'Cooperativa',key:'cooperative_name'}],d.items,r=>`<button class="table-action" data-audit="${r.id}">Detalhes</button>`));$$('[data-audit]').forEach(b=>b.onclick=()=>{const r=d.items.find(x=>String(x.id)===b.dataset.audit);openModal('Detalhes da auditoria',`<h3>Antes</h3><div class="code-box">${esc(pretty(r.before_json))}</div><h3>Depois</h3><div class="code-box">${esc(pretty(r.after_json))}</div>`)})};
function pretty(v){if(!v)return 'Sem dados';try{return JSON.stringify(JSON.parse(v),null,2)}catch{return v}}
pages.account=async()=>{$('#page-content').innerHTML=panel('Alterar senha',`<form id="password-form" class="form-grid">${field('Senha atual','current_password','','password','required')}${field('Nova senha','new_password','','password','required minlength="8"')}${buttons('Alterar senha')}</form>`);$('#password-form').onsubmit=async e=>{e.preventDefault();try{loading(true);await api('/api/auth/change-password',{method:'POST',body:formObject(e.currentTarget)});$('#password-form')?.reset();toast('Senha alterada.')}catch(err){toast(err.message,'error')}finally{loading(false)}}};

function updateOnlineControl(){const box=$('#online-control');box.classList.toggle('is-online',state.online);$('#online-label').textContent=state.online?'Online':'Offline';$('#online-toggle').textContent=state.online?'Ficar offline':'Ficar online'}
function currentPosition(){return new Promise((ok,no)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(ok,no,{enableHighAccuracy:true,timeout:15000,maximumAge:3000}):no(new Error('GPS indisponível.')))}
async function toggleOnline(){try{if(!state.online){const p=await currentPosition();await api('/api/app/driver/online',{method:'POST',body:{online:true,latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy}});state.online=true;startLocation();toast('Você está online e disponível para receber entregas.')}else{await api('/api/app/driver/online',{method:'POST',body:{online:false}});state.online=false;stopLocation();toast('Você está offline.')}updateOnlineControl()}catch(e){toast(e.message||'Autorize a localização para ficar online.','error')}}
function startLocation(){if(state.watchId!==null||!navigator.geolocation)return;let last=0;state.watchId=navigator.geolocation.watchPosition(async p=>{if(!state.online||Date.now()-last<8000)return;last=Date.now();const location={latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,speed:p.coords.speed,heading:p.coords.heading};try{await api('/api/app/driver/location',{method:'POST',body:location});const wait=await api('/api/app/v16/driver/wait/geofence',{method:'POST',body:location}).catch(()=>null);if(wait?.stopped){toast(wait.stage==='pickup'?'Você saiu da coleta. O cronômetro foi encerrado automaticamente.':'Você saiu da entrega. O cronômetro foi encerrado automaticamente.');if(state.page==='deliveries')navigate(state.page,false)}}catch{}},e=>toast(`GPS: ${e.message}`,'error'),{enableHighAccuracy:true,maximumAge:4000,timeout:20000})}
function stopLocation(){if(state.watchId!==null&&navigator.geolocation){navigator.geolocation.clearWatch(state.watchId);state.watchId=null}}

async function customerApp(mode='register'){
  if(typeof window.chegajaOpenCustomer==='function')return window.chegajaOpenCustomer(mode);
  showCustomer();
  $('#customer-content').innerHTML=`<section class="customer-hero"><p class="eyebrow">CHEGAJÁ PARA CLIENTES</p><h1>Link da cooperativa necessário</h1><p>O cadastro e o pedido só podem ser feitos pelo link oficial enviado pela cooperativa. Não existe escolha manual de cooperativa.</p></section>`;
}
function showCustomer(){$('#auth-screen').classList.add('hidden');$('#app-shell').classList.add('hidden');$('#tracking-screen').classList.add('hidden');$('#customer-screen').classList.remove('hidden')}
async function publicTracking(token){$('#auth-screen').classList.add('hidden');$('#app-shell').classList.add('hidden');$('#customer-screen').classList.add('hidden');const screen=$('#tracking-screen');screen.classList.remove('hidden');const refresh=async()=>{try{const d=await api(`/api/public/tracking/${encodeURIComponent(token)}`),x=d.item;screen.innerHTML=`<div class="tracking-card"><header class="tracking-head"><div><p class="eyebrow">Rastreamento</p><h1>${esc(x.establishment_name)}</h1><p>${esc(x.customer_name||'Entrega')}</p></div>${badge(x.status)}</header><div class="tracking-body"><div class="tracking-address"><div class="address-box"><small>Coleta</small><strong>${esc(x.pickup_address)}</strong></div><div class="address-box"><small>Entrega</small><strong>${esc(x.delivery_address)}</strong></div></div><div id="public-map" class="map small"></div><p class="muted">Cooperado: ${esc(x.driver_name||'Aguardando atribuição')} • Atualizado em ${dateTime(x.location_updated_at||x.updated_at)}</p></div></div>`;if(x.driver_lat!=null){const m=L.map('public-map').setView([x.driver_lat,x.driver_lng],15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(m);L.marker([x.driver_lat,x.driver_lng]).addTo(m).bindPopup(esc(x.driver_name||'Cooperado')).openPopup()}else $('#public-map').innerHTML=empty('Localização ainda indisponível','O cooperado aparecerá quando estiver online.')}catch(e){screen.innerHTML=`<div class="tracking-card"><div class="tracking-body">${empty('Rastreamento indisponível',e.message)}</div></div>`}};await refresh();state.timer=setInterval(refresh,6000)}

$('#login-form').onsubmit=async e=>{e.preventDefault();$('#login-message').textContent='';try{loading(true);const d=await api('/api/auth/login',{method:'POST',body:formObject(e.currentTarget)});state.token=d.token;localStorage.setItem('lg_token',d.token);await loadMe()}catch(err){$('#login-message').textContent=err.message}finally{loading(false)}};
$('#forgot-link').onclick=()=>showAuth('forgot');$$('.back-login').forEach(b=>b.onclick=()=>showAuth('login'));$('#forgot-form').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/forgot-password',{method:'POST',body:formObject(e.currentTarget)});$('#forgot-message').innerHTML=esc(d.message)+(d.development_reset_url?`<br><a href="${esc(d.development_reset_url)}">Abrir redefinição local</a>`:'')}catch(err){$('#forgot-message').textContent=err.message}};$('#reset-form').onsubmit=async e=>{e.preventDefault();const b=formObject(e.currentTarget);if(b.password!==b.confirm){$('#reset-message').textContent='As senhas não coincidem.';return}try{await api('/api/auth/reset-password',{method:'POST',body:{token:new URLSearchParams(location.search).get('reset'),password:b.password}});history.replaceState({},'',location.pathname);showAuth('login');toast('Senha atualizada.')}catch(err){$('#reset-message').textContent=err.message}};
$('#logout-button').onclick=()=>logout();$('#menu-button').onclick=()=>$('#sidebar').classList.toggle('open');$('#refresh-button').onclick=()=>navigate(state.page,false);$('#online-toggle').onclick=toggleOnline;$('#customer-app-link').onclick=customerApp;$('#customer-back-login').onclick=()=>showAuth('login');$('#modal')?.addEventListener('click',event=>event.stopPropagation());window.addEventListener('hashchange',()=>state.user&&navigate(location.hash.slice(1)||'dashboard',false));
async function init(){if('serviceWorker'in navigator){const local=['127.0.0.1','localhost'].includes(location.hostname);if(local){navigator.serviceWorker.getRegistrations().then(rs=>Promise.all(rs.map(r=>r.unregister()))).catch(()=>{});if('caches'in window)caches.keys().then(keys=>Promise.all(keys.map(k=>caches.delete(k)))).catch(()=>{})}else navigator.serviceWorker.register('/sw.js?v=14.15.8',{updateViaCache:'none'}).catch(()=>{})}const track=location.pathname.match(/^\/r\/([^/]+)/);if(track)return publicTracking(track[1]);if(location.pathname==='/cliente'||new URLSearchParams(location.search).has('cliente'))return customerApp();if(new URLSearchParams(location.search).has('reset'))return showAuth('reset');if(state.token){try{loading(true);await loadMe()}catch{logout(false)}finally{loading(false)}}else showAuth('login')}
